$t['The Companion Chat service is not available right now. Ask your site administrator to check the AI plugin connection.'] = 'خدمة Companion Chat غير متاحة حاليًا. اطلب من مسؤول الموقع التحقق من اتصال إضافة الذكاء الاصطناعي.';
$t['The connection could not be renewed. Please reconnect your account.'] = 'تعذّر تجديد الاتصال. يرجى إعادة ربط حسابك.';
