$t['The connection to the destination was dropped mid-stream. This may be a temporary network issue; FFMPEG will try to reconnect.'] = 'انقطع الاتصال بالوجهة أثناء البث. قد تكون هذه مشكلة مؤقتة في الشبكة؛ سيحاول FFMPEG إعادة الاتصال.';
$t['The connection to YouTube was interrupted. The upload was paused and can be resumed.'] = 'انقطع الاتصال بـ YouTube. تم إيقاف الرفع مؤقتًا ويمكن استئنافه.';
$t['The connection was interrupted. Check your account before retrying this subscription.'] = 'انقطع الاتصال. تحقق من حسابك قبل إعادة محاولة هذا الاشتراك.';
