$t['The converted files were kept. Contact the site administrator to retry the transfer; you do not need to upload the video again.'] = 'تم الاحتفاظ بالملفات المحوّلة. تواصل مع مسؤول الموقع لإعادة محاولة النقل؛ لا تحتاج إلى رفع الفيديو مرة أخرى.';
$t['The converted video could not be sent back to this site.'] = 'تعذّر إرسال الفيديو المحوّل إلى هذا الموقع.';
$t['The customers of the selected card. Search, sort, copy the e-mails or export everything to a spreadsheet.'] = 'عملاء البطاقة المحددة. ابحث وفرز وانسخ عناوين البريد الإلكتروني أو صدّر كل شيء إلى جدول بيانات.';
$t['The daily YouTube upload quota of this website was reached. Uploads become available again after midnight Pacific Time. Please try again later.'] = 'تم بلوغ الحد اليومي لرفع الفيديوهات إلى YouTube لهذا الموقع. يصبح الرفع متاحًا مجددًا بعد منتصف الليل بتوقيت المحيط الهادئ. يرجى المحاولة لاحقًا.';
$t['The database version changes only when a database migration is applied. It is not expected to match the release tag or commit.'] = 'يتغير إصدار قاعدة البيانات فقط عند تطبيق ترحيل لقاعدة البيانات. وليس من المتوقع أن يطابق وسم الإصدار أو الـ commit.';
$t['The default'] = 'الافتراضي';
$t['The destination RTMP server refused the connection. Check the stream URL and make sure the server is online.'] = 'رفض خادم RTMP الوجهة الاتصال. تحقق من رابط البث وتأكد من أن الخادم متصل.';
$t['The destination server requires authentication. Check the stream key.'] = 'يتطلب خادم الوجهة المصادقة. تحقق من مفتاح البث.';
$t['The destination server returned 403. The stream key may be invalid or expired.'] = 'أعاد خادم الوجهة الرمز 403. قد يكون مفتاح البث غير صالح أو منتهي الصلاحية.';
$t['The destination video was removed or this account cannot edit it. Check the video and account access on the site.'] = 'تمت إزالة فيديو الوجهة أو لا يملك هذا الحساب صلاحية تعديله. تحقق من الفيديو ومن صلاحيات الحساب على الموقع.';
$t['The download is controlled by the system, there is nothing to check on the user'] = 'The download is controlled by the system, there is nothing to check on the user';
