$t['The encoding queue is stalled'] = 'قائمة انتظار الترميز متوقفة';
$t['The event purchase could not be completed. Your wallet payment was not deducted. Check your balance before trying again.'] = 'تعذّر إتمام شراء الفعالية. لم يتم خصم المبلغ من محفظتك. تحقق من رصيدك قبل المحاولة مرة أخرى.';
$t['The file could not be converted. It may be damaged or use a format the encoder does not support.'] = 'تعذّر تحويل الملف. قد يكون تالفًا أو بتنسيق لا يدعمه المُرمِّز.';
$t['The file must be an .vtt file!'] = 'The file must be an .vtt file!';
