$t['The information above corresponds to our official records and confirms the authenticity of this certificate.'] = 'تتطابق المعلومات أعلاه مع سجلاتنا الرسمية وتؤكد صحة هذه الشهادة.';
$t['The input stream contains invalid data. The source HLS may not be ready yet or the stream was interrupted.'] = 'يحتوي البث الوارد على بيانات غير صالحة. قد لا يكون مصدر HLS جاهزًا بعد أو قد انقطع البث.';
