$t['The same alert is repeated at most every few hours while the problem continues.'] = 'يتكرر التنبيه نفسه مرة كل بضع ساعات على الأكثر ما دامت المشكلة مستمرة.';
$t['The selected camera or microphone is not available. Please choose another device.'] = 'الكاميرا أو الميكروفون المحدد غير متاح. يُرجى اختيار جهاز آخر.';
$t['The selected position is highlighted on a real page. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'يتم تمييز الموضع المحدد على صفحة حقيقية. معاينة الجوال تغيّر مواضع الإعلانات فقط؛ وبقية الصفحة تستخدم جهاز متصفحك.';
$t['The selected position is outlined on a real page of your site and follows the position you choose below. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'يتم تحديد الموضع المختار بإطار على صفحة حقيقية من موقعك، ويتبع الموضع الذي تختاره أدناه. معاينة الجوال تغيّر مواضع الإعلانات فقط؛ أما بقية الصفحة فتستخدم جهاز متصفحك.';
$t['The site is currently offline due to a database issue. We are working to resolve the problem as quickly as possible.'] = 'الموقع غير متاح حاليًا بسبب مشكلة في قاعدة البيانات. نعمل على حل المشكلة بأسرع وقت ممكن.';
$t['The site is temporarily unavailable because the server\'s disk is full. We are working on this issue and will be back shortly.'] = 'الموقع غير متاح مؤقتًا لأن قرص الخادم ممتلئ. نعمل على حل هذه المشكلة وسنعود قريبًا.';
$t['The site is undergoing maintenance as the server\'s disk is nearing capacity. We are addressing the issue and will be back shortly.'] = 'الموقع قيد الصيانة لأن قرص الخادم يقترب من سعته القصوى. نعمل على معالجة المشكلة وسنعود قريبًا.';
$t['The site refused access. Renew the encoder account access and check its upload permissions.'] = 'رفض الموقع الوصول. جدّد صلاحية وصول حساب المُرمِّز وتحقق من صلاحيات الرفع الخاصة به.';
$t['The site will display only a login form to un authenticated users'] = 'The site will display only a login form to un authenticated users';
