$t['YouTube: Google only lists channels you own or manage as a Brand Account. If your channel is not listed, fill in its stream URL and stream key by hand in the form.'] = 'YouTube: تعرض Google فقط القنوات التي تملكها أو تديرها كحساب علامة تجارية. إذا لم تكن قناتك مدرجة، فأدخل رابط البث ومفتاح البث يدويًا في النموذج.';
