$t['YouTube could not process the uploaded file. Check that the video plays correctly on this site and publish it again.'] = 'تعذر على YouTube معالجة الملف المرفوع. تحقق من أن الفيديو يعمل بشكل صحيح على هذا الموقع ثم انشره مرة أخرى.';
