$t['YouTube did not accept the description. Edit the description and publish again.'] = 'لم يقبل YouTube الوصف. عدّل الوصف ثم انشر مرة أخرى.';
$t['YouTube did not accept the selected category. Choose another category and publish again.'] = 'لم يقبل YouTube الفئة المحددة. اختر فئة أخرى ثم انشر مرة أخرى.';
$t['YouTube did not accept the selected privacy setting. Choose another one and publish again.'] = 'لم يقبل YouTube إعداد الخصوصية المحدد. اختر إعدادًا آخر ثم انشر مرة أخرى.';
$t['YouTube did not accept the tags. Edit the tags and publish again.'] = 'لم يقبل YouTube الوسوم. عدّل الوسوم ثم انشر مرة أخرى.';
$t['YouTube did not accept the title. Edit the title and publish again.'] = 'لم يقبل YouTube العنوان. عدّل العنوان ثم انشر مرة أخرى.';
$t['YouTube did not accept the video details. Check the title, description and tags, then publish again.'] = 'لم يقبل YouTube تفاصيل الفيديو. تحقق من العنوان والوصف والوسوم، ثم انشر مرة أخرى.';
$t['YouTube did not allow this upload. Reconnect your YouTube account and allow this website to manage your YouTube videos.'] = 'لم يسمح YouTube بهذا الرفع. أعد ربط حسابك على YouTube واسمح لهذا الموقع بإدارة مقاطع الفيديو الخاصة بك على YouTube.';
$t['YouTube is receiving too many requests right now. Please wait a few minutes and try again.'] = 'يتلقى YouTube عددًا كبيرًا جدًا من الطلبات حاليًا. يرجى الانتظار بضع دقائق والمحاولة مرة أخرى.';
$t['YouTube rejected the video because it does not follow the YouTube policies.'] = 'رفض YouTube الفيديو لأنه لا يتوافق مع سياسات YouTube.';
$t['YouTube rejected the video because it is a duplicate of a video already on your channel.'] = 'رفض YouTube الفيديو لأنه نسخة مكررة من فيديو موجود بالفعل على قناتك.';
$t['YouTube rejected the video because it is longer than your channel allows. Verify your YouTube account to upload longer videos.'] = 'رفض YouTube الفيديو لأنه أطول مما تسمح به قناتك. وثّق حسابك على YouTube لرفع مقاطع فيديو أطول.';
$t['YouTube rejected the video because of a copyright claim.'] = 'رفض YouTube الفيديو بسبب مطالبة بحقوق الطبع والنشر.';
$t['YouTube returned an unexpected error. Please try again later. If the problem continues, contact the site administrator.'] = 'أعاد YouTube خطأً غير متوقع. يرجى المحاولة مرة أخرى لاحقًا. إذا استمرت المشكلة، فتواصل مع مسؤول الموقع.';
